CREATE TABLE IF NOT EXISTS "Jobs" (
    "JobId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ShipmentType" VARCHAR(30),
    "ClientName" VARCHAR(250),
    "ClientReference" VARCHAR(150),
    "InvoiceNumber" VARCHAR(150),
    "Origin" VARCHAR(250),
    "Destination" VARCHAR(250),
    "JobStatus" VARCHAR(40) NOT NULL DEFAULT 'EmailReceived',
    "CreatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
    
CREATE TABLE IF NOT EXISTS "EmailMessages" (
    "EmailId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "JobId" BIGINT NOT NULL REFERENCES "Jobs" ("JobId"),
    "GmailMessageId" VARCHAR(100) NOT NULL UNIQUE,
    "GmailThreadId" VARCHAR(100),
    "Sender" VARCHAR(500),
    "Recipient" VARCHAR(1000),
    "Subject" VARCHAR(1000),
    "BodyText" TEXT,
    "BodyHtml" TEXT,
    "ReceivedAt" TIMESTAMPTZ(3),
    "GmailInternalDate" BIGINT,
    "ProcessingStatus" VARCHAR(40) NOT NULL DEFAULT 'Processing',
    "ProcessingError" TEXT,
    "CreatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "IX_EmailMessages_JobId" ON "EmailMessages" ("JobId");

CREATE TABLE IF NOT EXISTS "EmailFields" (
    "EmailFieldId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EmailId" BIGINT NOT NULL REFERENCES "EmailMessages" ("EmailId"),
    "JobId" BIGINT NOT NULL REFERENCES "Jobs" ("JobId"),
    "FieldKey" VARCHAR(100) NOT NULL,
    "FieldLabel" VARCHAR(150) NOT NULL,
    "FieldValue" VARCHAR(2000) NOT NULL,
    "CreatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE ("EmailId", "FieldKey")
);
CREATE INDEX IF NOT EXISTS "IX_EmailFields_JobId" ON "EmailFields" ("JobId");

CREATE TABLE IF NOT EXISTS "DocumentFiles" (
    "FileId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "JobId" BIGINT NOT NULL REFERENCES "Jobs" ("JobId"),
    "EmailId" BIGINT NOT NULL REFERENCES "EmailMessages" ("EmailId"),
    "GmailAttachmentId" VARCHAR(500),
    "OriginalFilename" VARCHAR(500) NOT NULL,
    "StoredFilename" VARCHAR(500) NOT NULL,
    "StoragePath" VARCHAR(1500) NOT NULL,
    "MimeType" VARCHAR(255),
    "FileSizeBytes" BIGINT NOT NULL,
    "Sha256" CHAR(64),
    "DocumentType" VARCHAR(60) NOT NULL DEFAULT 'Unknown',
    "StorageStatus" VARCHAR(40) NOT NULL DEFAULT 'Stored',
    "OcrStatus" VARCHAR(40) NOT NULL DEFAULT 'NotProcessed',
    "CreatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE ("EmailId", "GmailAttachmentId")
);
CREATE INDEX IF NOT EXISTS "IX_DocumentFiles_JobId" ON "DocumentFiles" ("JobId");
CREATE INDEX IF NOT EXISTS "IX_DocumentFiles_EmailId" ON "DocumentFiles" ("EmailId");

CREATE TABLE IF NOT EXISTS "GmailSyncState" (
    "StateKey" VARCHAR(100) PRIMARY KEY,
    "StateValue" VARCHAR(1000) NOT NULL,
    "UpdatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
